def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count positive multiples of k with equally many even and odd digits.

    Both range endpoints are inclusive. Leading zeroes do not count as digits.
    Digit DP uses O(k * d**2) states and O(10 * k * d**2) time for d digits.
    """
    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))
        length = len(digits)

        @cache
        def visit(position: int, remainder: int, balance: int,
                  started: bool, tight: bool) -> int:
            remaining = length - position
            if started and (abs(balance) > remaining
                            or (remaining - balance) % 2 != 0):
                return 0
            if position == length:
                return int(started and balance == 0 and remainder == 0)

            ceiling = digits[position] if tight else 9
            total = 0
            for digit in range(ceiling + 1):
                next_tight = tight and digit == digits[position]
                if not started and digit == 0:
                    total += visit(position + 1, 0, 0, False, next_tight)
                else:
                    total += visit(
                        position + 1,
                        (remainder * 10 + digit) % k,
                        balance + (1 if digit % 2 == 0 else -1),
                        True,
                        next_tight,
                    )
            return total

        return visit(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)


def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive, digit-limited integers with suffix s in [start, finish].

    Write each candidate uniquely as prefix * 10**len(s) + int(s), then
    count digit-limited prefixes directly. The number of digit steps is
    O(len(s) + log(finish)); auxiliary space is O(log(finish)).
    """
    if any(int(digit) > limit for digit in s):
        return 0

    suffix = int(s)
    scale = 10 ** len(s)
    base = limit + 1
    zero_prefix_allowed = suffix > 0 and s[0] != "0"

    def count_up_to(bound: int) -> int:
        maximum = (bound - suffix) // scale
        if maximum < 0:
            return 0
        digits = str(maximum)
        powers = [1]
        for _ in range(len(digits)):
            powers.append(powers[-1] * base)

        total = 0
        for position, character in enumerate(digits):
            digit = int(character)
            remaining = len(digits) - position - 1
            total += min(digit, base) * powers[remaining]
            if digit > limit:
                break
        else:
            total += 1  # The maximum itself has only allowed digits.

        # Prefix zero only works when s itself is a positive canonical numeral.
        return total - (0 if zero_prefix_allowed else 1)

    return count_up_to(finish) - count_up_to(start - 1)


def count_valid_colorings(n: int, m: int) -> int:
    """Count proper colorings of a labeled n-cycle, modulo 998244353.

    The cycle's chromatic polynomial is
    (m - 1)**n + (-1)**n * (m - 1).
    Time: O(log n). Auxiliary space: O(1).
    """
    modulus = 998244353
    colors_minus_one = m - 1
    correction = colors_minus_one if n % 2 == 0 else -colors_minus_one
    return (pow(colors_minus_one, n, modulus) + correction) % modulus


def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Return twice the black wallpaper area of [A, C] x [B, D].

    The doubled unit-cell areas repeat every four columns and two rows:
        y even: 2, 1, 0, 1
        y odd:  1, 2, 1, 0
    Signed prefix areas handle negative coordinates without translation.
    Time and auxiliary space: O(1).
    """
    column_prefix = (0, 3, 6, 7, 8)
    lower_row_prefix = (0, 2, 3, 3, 4)

    def prefix(x: int, y: int) -> int:
        full_columns, extra_columns = divmod(x, 4)
        full_rows, extra_row = divmod(y, 2)
        return (
            8 * full_columns * full_rows
            + full_rows * column_prefix[extra_columns]
            + 4 * full_columns * extra_row
            + extra_row * lower_row_prefix[extra_columns]
        )

    return prefix(C, D) - prefix(A, D) - prefix(C, B) + prefix(A, B)


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Find the kth distinct positive multiple of at least one denomination.

    Remove redundant denominations, combine inclusion-exclusion terms sharing
    an LCM, and binary-search the first amount with at least k predecessors
    including itself. With r nonredundant coins and t distinct relevant LCMs,
    time is O(r*t + t*log(min(coins)*k)) and auxiliary space is O(t).
    The input list is not modified.
    """
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % divisor == 0 for divisor in denominations):
            denominations.append(coin)

    if len(denominations) == 1:
        return denominations[0] * k

    upper = denominations[0] * k
    coefficients = {}
    for coin in denominations:
        if coin > upper:
            continue
        changes = {coin: 1}
        for multiple, coefficient in coefficients.items():
            combined = lcm(multiple, coin)
            if combined <= upper:
                changes[combined] = changes.get(combined, 0) - coefficient
        for multiple, change in changes.items():
            updated = coefficients.get(multiple, 0) + change
            if updated:
                coefficients[multiple] = updated
            else:
                coefficients.pop(multiple, None)

    terms = tuple(coefficients.items())
    lower = denominations[0]
    while lower < upper:
        middle = (lower + upper) // 2
        count = sum(coefficient * (middle // multiple)
                    for multiple, coefficient in terms)
        if count >= k:
            upper = middle
        else:
            lower = middle + 1
    return lower


def min_absolute_difference(nums: List[int], k: int) -> int:
    """Minimize abs(k - subarray_OR) over nonempty contiguous subarrays.

    At each endpoint, retain only distinct OR values for subarrays ending
    there. Extending a subarray can add each bit at most once, so there are
    O(b) such values for b-bit inputs. Time: O(len(nums)*b); space: O(b).
    The input list is not modified. Empty input raises ValueError.
    """
    if not nums:
        raise ValueError("nums must contain at least one element")
    best = abs(nums[0] - k)
    ending_ors = set()
    for value in nums:
        ending_ors = {value} | {previous | value for previous in ending_ors}
        for combined in ending_ors:
            difference = abs(combined - k)
            if difference == 0:
                return 0
            if difference < best:
                best = difference
    return best
